def transform(grid):
    """Transform: change all 8s to 2s, and 7s that are in rows/cols with 8s."""
    rows = len(grid)
    cols = len(grid[0])

    # Find rows that are entirely the same non-zero value
    target_rows = set()
    for r in range(rows):
        if rows > 0 and all(grid[r][c] == grid[r][0] and grid[r][0] != 0 for c in range(cols)):
            target_rows.add(r)

    # Apply transformation
    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            target_val = grid[r][0] if r in target_rows else None
            if target_val is not None:
                if grid[r][c] == target_val:
                    result[r][c] = 2

    return result

