from collections import Counter

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    val_counts = Counter([grid[r][c] for r in range(rows) for c in range(cols)])

    # Find uniform rows and columns for each value
    uniform_rows = {}
    uniform_cols = {}

    for val in val_counts:
        uniform_rows[val] = set()
        uniform_cols[val] = set()

        # Uniform rows
        for r in range(rows):
            if len(set(grid[r][c] for c in range(cols))) == 1:
                uniform_rows[val].add(r)

        # Uniform cols
        for c in range(cols):
            if len(set(grid[r][c] for r in range(rows))) == 1:
                uniform_cols[val].add(c)

    # Target = value with uniform lines >= 2
    target_val = None
    max_lines = 0

    for val in val_counts:
        lines = len(uniform_rows[val]) + len(uniform_cols[val])
        if lines >= 2 and lines > max_lines:
            max_lines = lines
            target_val = val

    if target_val is None:
        return grid

    # Output: all 6s in uniform lines → 2
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    uniform_row_set = uniform_rows.get(target_val, set())
    uniform_col_set = uniform_cols.get(target_val, set())

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_val and (r in uniform_row_set or c in uniform_col_set):
                output[r][c] = 2

    return output
